def _round_dir_is_fresh(round_dir: Path, mark_ts: int | None) -> bool:
    if (round_dir / "round-start-s").is_file():
        return True
    if mark_ts is None:
        return round_dir.is_dir()
    try:
        for child in round_dir.iterdir():
            try:
                if child.is_file() and child.stat().st_mtime > mark_ts:
                    return True
            except OSError:
                continue
    except OSError:
        pass
    return False


